412→// FetchMetadataTreeOnly fetches the tip of the entire/checkpoints/v1 branch
413→// from origin with --depth=1 --filter=blob:none, downloading only the latest
414→// commit and its tree objects (no blobs, no history).
415→// After this call, tree navigation via go-git works but blob reads will fail
416→// for objects that weren't previously fetched.
417→// Uses git CLI for credential helper support.
418→func FetchMetadataTreeOnly(ctx context.Context) error {
419→	branchName := paths.MetadataBranchName
420→
421→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
422→	defer cancel()
423→
424→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
425→
426→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "--depth=1", "--filter=blob:none", "origin", refSpec)
427→	if output, err := fetchCmd.CombinedOutput(); err != nil {
428→		if ctx.Err() == context.DeadlineExceeded {
429→			return errors.New("treeless fetch timed out after 2 minutes")
430→		}
431→		return fmt.Errorf("failed to treeless-fetch %s from origin: %s: %w", branchName, strings.TrimSpace(string(output)), err)
432→	}
433→
434→	repo, err := openRepository(ctx)
435→	if err != nil {
436→		return fmt.Errorf("failed to open repository: %w", err)
437→	}
438→
439→	// Get the remote branch reference
440→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
441→	if err != nil {
442→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
443→	}
444→
445→	// Create or update local branch pointing to the same commit
446→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
447→	if err := repo.Storer.SetReference(localRef); err != nil {
448→		return fmt.Errorf("failed to create local %s branch: %w", branchName, err)
449→	}
450→
451→	return nil
452→}
453→
454→// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
455→// Uses git fetch-pack to request individual objects, which works when the server
456→// supports allow-reachable-sha1-in-want (GitHub, GitLab, Bitbucket all do).
457→//
458→// If fetch-pack fails (e.g., old server without SHA-in-want support), falls back
459→// to a full metadata branch fetch.
460→func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
461→	if len(hashes) == 0 {
462→		return nil
463→	}
464→
465→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
466→	defer cancel()
467→
468→	// Get remote URL for fetch-pack
469→	urlCmd := exec.CommandContext(ctx, "git", "remote", "get-url", "origin")
470→	urlOutput, err := urlCmd.Output()
471→	if err != nil {
472→		return fmt.Errorf("failed to get remote URL: %w", err)
473→	}
474→	remoteURL := strings.TrimSpace(string(urlOutput))
475→
476→	// Build fetch-pack args with blob hashes
477→	args := []string{"fetch-pack", "--thin", "--no-progress", remoteURL}
478→	for _, h := range hashes {
479→		args = append(args, h.String())
480→	}
481→
482→	fetchCmd := exec.CommandContext(ctx, "git", args...)
483→	if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
484→		// Fallback: full metadata branch fetch (pack negotiation skips already-local objects)
485→		if fallbackErr := FetchMetadataBranch(ctx); fallbackErr != nil {
486→			return fmt.Errorf("fetch-pack failed (%s: %w) and fallback fetch also failed: %w",
487→				strings.TrimSpace(string(output)), fetchErr, fallbackErr)
488→		}
489→	}

