129→// FindEntry search a TreeEntry in this tree or any subtree.
130→func (t *Tree) FindEntry(path string) (*TreeEntry, error) {
131→	if t.t == nil {
132→		t.t = make(map[string]*Tree)
133→	}
134→
135→	pathParts := strings.Split(path, "/")
136→	startingTree := t
137→	pathCurrent := ""
138→
139→	// search for the longest path in the tree path cache
140→	for i := len(pathParts) - 1; i >= 1; i-- {
141→		path := filepath.Join(pathParts[:i]...)
142→
143→		tree, ok := t.t[path]
144→		if ok {
145→			startingTree = tree
146→			pathParts = pathParts[i:]
147→			pathCurrent = path
148→
149→			break
150→		}
151→	}
152→
153→	var tree *Tree
154→	var err error
155→	for tree = startingTree; len(pathParts) > 1; pathParts = pathParts[1:] {
156→		if tree, err = tree.dir(pathParts[0]); err != nil {
157→			return nil, err
158→		}
159→
160→		pathCurrent = filepath.Join(pathCurrent, pathParts[0])
161→		t.t[pathCurrent] = tree
162→	}
163→
164→	return tree.entry(pathParts[0])
165→}
