215→// Decode transform an plumbing.EncodedObject into a Tree struct
216→func (t *Tree) Decode(o plumbing.EncodedObject) (err error) {
217→	if o.Type() != plumbing.TreeObject {
218→		return ErrUnsupportedObject
219→	}
220→
221→	t.Hash = o.Hash()
222→	if o.Size() == 0 {
223→		return nil
224→	}
225→
226→	t.Entries = nil
227→	t.m = nil
228→
229→	reader, err := o.Reader()
230→	if err != nil {
231→		return err
232→	}
233→	defer ioutil.CheckClose(reader, &err)
234→
235→	r := sync.GetBufioReader(reader)
236→	defer sync.PutBufioReader(r)
237→
238→	for {
239→		str, err := r.ReadString(' ')
240→		if err != nil {
241→			if err == io.EOF {
242→				break
243→			}
244→
245→			return err
246→		}
247→		str = str[:len(str)-1] // strip last byte (' ')
248→
249→		mode, err := filemode.New(str)
250→		if err != nil {
251→			return err
252→		}
253→
254→		name, err := r.ReadString(0)
255→		if err != nil && err != io.EOF {
256→			return err
257→		}
258→
259→		var hash plumbing.Hash
260→		hash.ResetBySize(t.Hash.Size())
261→		if _, err = hash.ReadFrom(r); err != nil {
262→			return err
263→		}
264→
265→		baseName := name[:len(name)-1]
266→		t.Entries = append(t.Entries, TreeEntry{
267→			Hash: hash,
268→			Mode: mode,
269→			Name: baseName,
270→		})
271→	}
272→
273→	return nil
274→}
