276→// TreeEntrySorter is a helper type for sorting TreeEntry slices.
277→type TreeEntrySorter []TreeEntry
278→
279→func (s TreeEntrySorter) Len() int {
280→	return len(s)
281→}
282→
283→func (s TreeEntrySorter) Less(i, j int) bool {
284→	name1 := s[i].Name
285→	name2 := s[j].Name
286→	if s[i].Mode == filemode.Dir {
287→		name1 += "/"
288→	}
289→	if s[j].Mode == filemode.Dir {
290→		name2 += "/"
291→	}
292→	return name1 < name2
293→}
294→
295→func (s TreeEntrySorter) Swap(i, j int) {
296→	s[i], s[j] = s[j], s[i]
297→}
