299→// Encode transforms a Tree into a plumbing.EncodedObject.
300→// The tree entries must be sorted by name.
301→func (t *Tree) Encode(o plumbing.EncodedObject) (err error) {
302→	o.SetType(plumbing.TreeObject)
303→	w, err := o.Writer()
304→	if err != nil {
305→		return err
306→	}
307→
308→	defer ioutil.CheckClose(w, &err)
309→
310→	if !sort.IsSorted(TreeEntrySorter(t.Entries)) {
311→		return ErrEntriesNotSorted
312→	}
313→
314→	for _, entry := range t.Entries {
315→		if strings.IndexByte(entry.Name, 0) != -1 {
316→			return fmt.Errorf("malformed filename %q", entry.Name)
317→		}
318→		if _, err = fmt.Fprintf(w, "%o %s", entry.Mode, entry.Name); err != nil {
319→			return err
320→		}
321→
322→		if _, err = w.Write([]byte{0x00}); err != nil {
323→			return err
324→		}
325→
326→		if _, err = entry.Hash.WriteTo(w); err != nil {
327→			return err
328→		}
329→	}
330→
331→	return err
332→}
