377→// treeEntryIter facilitates iterating through the TreeEntry objects in a Tree.
378→type treeEntryIter struct {
379→	t   *Tree
380→	pos int
381→}
382→
383→func (iter *treeEntryIter) Next() (TreeEntry, error) {
384→	if iter.pos >= len(iter.t.Entries) {
385→		return TreeEntry{}, io.EOF
386→	}
387→	iter.pos++
388→	return iter.t.Entries[iter.pos-1], nil
