391→// TreeWalker provides a means of walking through all of the entries in a Tree.
392→type TreeWalker struct {
393→	stack     []*treeEntryIter
394→	base      string
395→	recursive bool
396→	seen      map[plumbing.Hash]bool
397→
398→	s storer.EncodedObjectStorer
399→	t *Tree
400→}
401→
402→// NewTreeWalker returns a new TreeWalker for the given tree.
403→//
404→// It is the caller's responsibility to call Close() when finished with the
405→// tree walker.
406→func NewTreeWalker(t *Tree, recursive bool, seen map[plumbing.Hash]bool) *TreeWalker {
407→	stack := make([]*treeEntryIter, 0, startingStackSize)
408→	stack = append(stack, &treeEntryIter{t, 0})
409→
410→	return &TreeWalker{
411→		stack:     stack,
412→		recursive: recursive,
413→		seen:      seen,
414→
415→		s: t.s,
416→		t: t,
417→	}
418→}
419→
420→// Next returns the next object from the tree. Objects are returned in order
421→// and subtrees are included. After the last object has been returned further
422→// calls to Next() will return io.EOF.
423→//
424→// In the current implementation any objects which cannot be found in the
425→// underlying repository will be skipped automatically. It is possible that this
426→// may change in future versions.
427→func (w *TreeWalker) Next() (name string, entry TreeEntry, err error) {
428→	var obj *Tree
429→	for {
430→		current := len(w.stack) - 1
431→		if current < 0 {
432→			// Nothing left on the stack so we're finished
433→			err = io.EOF
434→			return name, entry, err
435→		}
436→
437→		if current > maxTreeDepth {
438→			// We're probably following bad data or some self-referencing tree
439→			err = ErrMaxTreeDepth
440→			return name, entry, err
441→		}
442→
443→		entry, err = w.stack[current].Next()
444→		if err == io.EOF {
445→			// Finished with the current tree, move back up to the parent
446→			w.stack = w.stack[:current]
447→			w.base, _ = path.Split(w.base)
448→			w.base = strings.TrimSuffix(w.base, "/")
449→			continue
450→		}
451→
452→		if err != nil {
453→			return name, entry, err
454→		}
455→
456→		if w.seen[entry.Hash] {
457→			continue
458→		}
459→
460→		if entry.Mode == filemode.Dir {
461→			obj, err = GetTree(w.s, entry.Hash)
462→		}
463→
464→		name = simpleJoin(w.base, entry.Name)
465→
466→		if err != nil {
467→			err = io.EOF
468→			return name, entry, err
469→		}
470→
471→		break
472→	}
473→
474→	if !w.recursive {
475→		return name, entry, err
476→	}
477→
478→	if obj != nil {
479→		w.stack = append(w.stack, &treeEntryIter{obj, 0})
480→		w.base = simpleJoin(w.base, entry.Name)
481→	}
482→
483→	return name, entry, err
484→}
485→
486→// Tree returns the tree that the tree walker most recently operated on.
487→func (w *TreeWalker) Tree() *Tree {
488→	current := len(w.stack) - 1
489→	if w.stack[current].pos == 0 {
490→		current--
491→	}
492→
493→	if current < 0 {
494→		return nil
495→	}
496→
497→	return w.stack[current].t
498→}
499→
500→// Close releases any resources used by the TreeWalker.
501→func (w *TreeWalker) Close() {
502→	w.stack = nil
503→}
