505→// TreeIter provides an iterator for a set of trees.
506→type TreeIter struct {
507→	storer.EncodedObjectIter
508→	s storer.EncodedObjectStorer
509→}
510→
511→// NewTreeIter takes a storer.EncodedObjectStorer and a
512→// storer.EncodedObjectIter and returns a *TreeIter that iterates over all
513→// tree contained in the storer.EncodedObjectIter.
514→//
515→// Any non-tree object returned by the storer.EncodedObjectIter is skipped.
516→func NewTreeIter(s storer.EncodedObjectStorer, iter storer.EncodedObjectIter) *TreeIter {
517→	return &TreeIter{iter, s}
518→}
519→
520→// Next moves the iterator to the next tree and returns a pointer to it. If
521→// there are no more trees, it returns io.EOF.
522→func (iter *TreeIter) Next() (*Tree, error) {
523→	for {
524→		obj, err := iter.EncodedObjectIter.Next()
525→		if err != nil {
526→			return nil, err
527→		}
528→
529→		if obj.Type() != plumbing.TreeObject {
530→			continue
531→		}
532→
533→		return DecodeTree(iter.s, obj)
534→	}
535→}
536→
537→// ForEach call the cb function for each tree contained on this iter until
538→// an error happens or the end of the iter is reached. If ErrStop is sent
539→// the iteration is stop but no error is returned. The iterator is closed.
540→func (iter *TreeIter) ForEach(cb func(*Tree) error) error {
541→	return iter.EncodedObjectIter.ForEach(func(obj plumbing.EncodedObject) error {
542→		if obj.Type() != plumbing.TreeObject {
543→			return nil
544→		}
545→
546→		t, err := DecodeTree(iter.s, obj)
547→		if err != nil {
548→			return err
549→		}
550→
551→		return cb(t)
552→	})
553→}
554→
555→func simpleJoin(parent, child string) string {
556→	if len(parent) > 0 {
557→		return parent + "/" + child
558→	}
559→	return child
560→}
