// fetchBlobIfMissing uses FindEntry to locate the blob hash for the given path
// (navigating only tree objects), checks if the blob exists locally, and fetches
// it from the remote if missing.
func (t *FetchingTree) fetchBlobIfMissing(path string) {
	if t.fetch == nil {
		return
