	entry, err := t.inner.FindEntry(path)
	if err != nil {
		logging.Debug(t.ctx, "FetchingTree.fetchBlobIfMissing: entry not found",
			slog.String("path", path),
			slog.String("error", err.Error()),
		)
		return
	}

	if t.resolver.HasBlob(entry.Hash) {
		logging.Debug(t.ctx, "FetchingTree.fetchBlobIfMissing: blob already local",
			slog.String("path", path),
			slog.String("hash", entry.Hash.String()[:12]),
