	}

	logging.Debug(t.ctx, "FetchingTree.fetchBlobIfMissing: fetching blob",
		slog.String("path", path),
		slog.String("hash", entry.Hash.String()[:12]),
	)
	if fetchErr := t.fetch(t.ctx, []plumbing.Hash{entry.Hash}); fetchErr != nil {
